<?php
declare(strict_types=1);namespace Atlas\Platform\Organizations\Onboarding;use Atlas\Platform\Core\Audit\AuditRecorder;use RuntimeException;final class WordPressOrganizationOnboardingRepository implements OrganizationOnboardingRepository{public function __construct(private object$db,private AuditRecorder$audit){}public function create(string$key,string$fingerprint,string$name,string$slug,int$userId):array{$operations=$this->db->prefix.'atlas_organization_operations';$existing=$this->db->get_row($this->db->prepare("SELECT fingerprint, organization_id, membership_id FROM `{$operations}` WHERE operation_key = %s",$key),ARRAY_A);if(is_array($existing)){if(!hash_equals((string)$existing['fingerprint'],$fingerprint)){throw new RuntimeException('The idempotency key was already used for a different request.');}return['organization_id'=>(string)$existing['organization_id'],'membership_id'=>(string)$existing['membership_id'],'replayed'=>true];}$organizationId=wp_generate_uuid4();$membershipId=wp_generate_uuid4();$now=current_time('mysql',true);$this->query('START TRANSACTION');try{$this->insert($this->db->prefix.'atlas_organizations',['id'=>$organizationId,'name'=>$name,'slug'=>$slug,'status'=>'active','created_at'=>$now,'updated_at'=>$now]);$this->insert($this->db->prefix.'atlas_organization_memberships',['id'=>$membershipId,'organization_id'=>$organizationId,'user_id'=>$userId,'status'=>'active','roles_json'=>wp_json_encode(['organization_admin']),'created_at'=>$now,'updated_at'=>$now]);$this->insert($operations,['operation_key'=>$key,'fingerprint'=>$fingerprint,'organization_id'=>$organizationId,'membership_id'=>$membershipId,'created_at'=>$now]);$this->audit->record('organization.created','organizations',$userId,$organizationId,'organization',$organizationId,['membership_id'=>$membershipId]);$this->query('COMMIT');}catch(\Throwable$failure){$this->query('ROLLBACK');$race=$this->db->get_row($this->db->prepare("SELECT fingerprint, organization_id, membership_id FROM `{$operations}` WHERE operation_key = %s",$key),ARRAY_A);if(is_array($race)&&hash_equals((string)$race['fingerprint'],$fingerprint)){return['organization_id'=>(string)$race['organization_id'],'membership_id'=>(string)$race['membership_id'],'replayed'=>true];}throw$failure;}return['organization_id'=>$organizationId,'membership_id'=>$membershipId,'replayed'=>false];}private function insert(string$table,array$data):void{if($this->db->insert($table,$data)===false){throw new RuntimeException('Organization onboarding could not be persisted.');}}private function query(string$sql):void{if($this->db->query($sql)===false){throw new RuntimeException('Organization onboarding transaction failed.');}}}
